#define ITER_LIM int(10.*(1.+iTime))
#define OFFSET vec2(-0.99939, 0.280351)

vec2 cmul(vec2 a, vec2 b)
{
    return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);
}

vec2 quadratic_map(vec2 z, vec2 c)
{
    return cmul(z, z) + c;
}

int diverge_time(vec2 c)
{
    vec2 z = vec2(0);
    int t = 0;
    while (dot(z,z) < 4. && t < ITER_LIM)
    {
        z = quadratic_map(z, c);
        t++;
    }

    return t;
}

float gray_map(int t)
{
    float x = float(t)/float(ITER_LIM);
    return 1. - x*x;
}

vec2 frag2uv(vec2 fragCoord)
{
    vec2 uv_0 = 2.*(fragCoord - iResolution.xy/2.)/iResolution.y;
    return OFFSET + uv_0/pow(1.35, min(iTime, 35.));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = frag2uv(fragCoord);

    vec3 col = vec3(1.);

    int t = diverge_time(uv);

    col = vec3(gray_map(t));

    // Output to screen
    fragColor = vec4(col,1.0);
}
